<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Bouncing Ball Physics Playground</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            background-color: #1a1f2e; /* Dark theme */
            font-family: sans-serif;
        }

        .container {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        canvas {
            border-radius: 10px;
            background-color: #1a1f2e;
            box-shadow: 0 4px 8px rgba(255,255,255,0.2);
            margin-bottom: 20px;
        }

        button {
            padding: 8px 15px;
            font-size: 14px;
            cursor: pointer;
            background-color: #ff6b6b;
            color: white;
            border: none;
            border-radius: 5px;
            transition: background-color 0.2s;
        }

        button:hover {
            background-color: #ee5253;
        }
    </style>
</head>
<body>
    <div class="container">
        <!-- Simulation Canvas -->
        <canvas id="sim"></canvas>

        <!-- Buttons -->
        <button id="drop">Drop Ball</button>
        <button id="play">Play Animation</button>
        <button id="clear">Clear All Balls</button>
    </div>

    <script>
        window.sim = {
            w: 400, // Canvas size in pixels
            h: 400,
            marginLeft: 10,
            marginTop: 20,
            balls: [],
            addBall(x, y, vx=0, vy=0, r?), // Note: r is used but not actually needed for physics
            clear(),
            step(dt) {
                const width = window.sim.w;
                const height = window.sim.h;
                const gravityFactor = 0.001; // Small force to simulate gravity

                // Draw the canvas background
                function drawCanvas() {
                    const canvas = document.getElementById('sim');
                    canvas.getContext('2d').clearRect(0, 0, width, height);

                    // Black background with slight glow for visual feedback
                    canvas.style.backgroundColor = '#000';
                    canvas.style.boxShadow = '0 4px 8px rgba(0,0,0,0.5)';
                }

                drawCanvas();
            },

            addBall(x, y, vx=0, vy=0, r) {
                // Add ball at cursor position
                const containerRect = getComputedStyle(document.getElementById('sim')).width + 'px';
                window.sim.balls.push({
                    x: Math.round(x),
                    y: Math.round(y),
                    vx: vx,
                    vy: vy,
                    r: r // radius parameter (though not used for drawing)
                });

                // Draw ball
                function drawBall(ball) {
                    const canvas = document.getElementById('sim');
                    const ctx = canvas.getContext('2d');

                    // Circle drawing with radius
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
                    ctx.fillStyle = '#ff6b6b'; // Ball color (for visual feedback)
                    ctx.fill();
                }

                drawBall(window.sim.balls[window.sim.balls.length - 1]);
            },

            clear() {
                window.sim.balls = [];
                window.sim.clear(); // Clear all balls
            },

            step(dt) {
                const width = window.sim.w;
                const height = window.sim.h;
                const gravityFactor = 0.001 * dt; // Smaller factor for visual effect

                // Update vy by gravity (increase downward)
                for (let i = 0; i < window.sim.balls.length; i++) {
                    const ball = window.sim.balls[i];

                    // Check collisions with walls
                    if (
                        Math.abs(ball.x) <= width/2 || 
                        Math.abs(ball.y) <= height/2 ||
                        ball.vx > 0 && x < 0 || ball.vx < 0 && x > 0,
                        ball.vy > 0 && y < 0 || ball.vy < 0 && y > 0
                    ) {

                        // Clamp position if near edge
                        let clampedX, clampedY;
                        if (Math.abs(ball.x) <= width/2) {
                            clampedX = Math.max(0, Math.min(width, ball.x));
                            window.sim.balls[i].x = clampedX;
                        }
                        if (Math.abs(ball.y) <= height/2) {
                            clampedY = Math.max(-height, Math.min(height, ball.y));
                            window.sim.balls[i].y = clampedY;
                        }

                        // Reverse velocity component perpendicular to wall
                        const oppositeVelocityX = ball.vx < 0 ? -ball.vx : ball.vx;
                        const oppositeVelocityY = ball.vy < 0 ? -ball.vy : ball.vy;

                        window.sim.balls[i].vx += oppositeVelocityX * dt / width; // x component
                        window.sim.balls[i].vy += oppositeVelocityY * dt / height; // y component

                        // Update velocity (this handles bouncing)
                    }
                }

                // Draw all balls with new velocities (for immediate visual update after step)
                for (let i = 0; i < window.sim.balls.length; i++) {
                    drawBall(window.sim.balls[i]);
                }
            }
        },

        // Helper to get canvas dimensions
        function getCanvasDimensions() {
            const canvas = document.getElementById('sim');
            return canvas.width + 'px', canvas.height + 'px';
        }
    </script>
</body>
</html>
